const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Lake Erie and upstate New York
  const lakeErie = ee.Geometry.Polygon([
    [[-83.5, 41.3], [-83.5, 42.9], [-78.5, 42.9], [-78.5, 41.3], [-83.5, 41.3]]
  ]);

  // 2. Dates
  const date1 = '2020-02-22';
  const date2 = '2020-03-01';

  // 3. Load MODIS Snow Cover data
  const modisSnow = ee.ImageCollection('MODIS/061/MOD10A1');

  // Get images for both dates
  const img1 = modisSnow
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .filterBounds(lakeErie)
    .select('NDSI_Snow_Cover')
    .first();

  const img2 = modisSnow
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .filterBounds(lakeErie)
    .select('NDSI_Snow_Cover')
    .first();

  // Check if images exist
  const img1Exists = await new Promise((resolve) => {
    img1.getInfo((result, error) => {
      resolve(!error && result !== null);
    });
  });

  const img2Exists = await new Promise((resolve) => {
    img2.getInfo((result, error) => {
      resolve(!error && result !== null);
    });
  });

  if (!img1Exists || !img2Exists) {
    console.log("Missing data for one or both dates.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Mask clouds and water, keep only valid snow pixels
  const maskSnow = function(image) {
    const snowCover = image.select('NDSI_Snow_Cover');
    // Values 0-100 are valid snow cover, 200=missing data, 201=no decision, 211=night, 250=cloud, 254=detector saturated, 255=fill
    const validMask = snowCover.gte(0).and(snowCover.lte(100));
    return snowCover.updateMask(validMask);
  };

  const snow1 = maskSnow(img1);
  const snow2 = maskSnow(img2);

  // 5. Calculate statistics
  const stats1 = await new Promise((resolve) => {
    snow1.reduceRegion({
      reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
      geometry: lakeErie,
      scale: 5000,
      maxPixels: 1e9
    }).getInfo((result) => resolve(result));
  });

  const stats2 = await new Promise((resolve) => {
    snow2.reduceRegion({
      reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
      geometry: lakeErie,
      scale: 5000,
      maxPixels: 1e9
    }).getInfo((result) => resolve(result));
  });

  const mean1 = stats1.NDSI_Snow_Cover_mean;
  const count1 = stats1.NDSI_Snow_Cover_count;
  const mean2 = stats2.NDSI_Snow_Cover_mean;
  const count2 = stats2.NDSI_Snow_Cover_count;

  console.log(`Feb 22, 2020: Mean=${mean1?.toFixed(2) || 'N/A'}, Pixels=${count1 || 0}`);
  console.log(`Mar 1, 2020: Mean=${mean2?.toFixed(2) || 'N/A'}, Pixels=${count2 || 0}`);

  // 6. Validation
  if (count1 === 0 || count2 === 0) {
    console.log("No valid pixels after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (mean1 == null || mean2 == null || isNaN(mean1) || isNaN(mean2)) {
    console.log("Calculation failed - invalid values.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 7. Compare snow cover
  console.log(`Snow cover difference: ${(mean2 - mean1).toFixed(2)} (positive = more on Mar 1)`);

  if (mean2 > mean1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
